class PanelAnimManager
{
    char data[128] __attribute__((aligned(16)));
public:
    ~PanelAnimManager();
};

class PanelFile
{
    char data[52];
public:
    ~PanelFile();
};

struct string_buf;
class stringx
{
protected:
    char* chars;
    string_buf* my_buf;
public:
    ~stringx();
};

class FEManager;
class FrontEnd
{
public:
    PanelAnimManager pam;
    PanelFile panel;
    FrontEnd* next;
    stringx path;
    FEManager* manager;

    virtual ~FrontEnd() {}
};

class PanelQuad;
class TextString
{
public:
    virtual ~TextString();
};

class HelpbarFE : public FrontEnd
{
private:
    enum {
        ARROW_H,
        ARROW_V,
        ARROW_BOTH,
        CROSS,
        TRIANGLE,
        CIRCLE,
        SQUARE,
        BTN_NUM
    };

    PanelQuad* buttons[BTN_NUM];
    TextString* help_text[BTN_NUM];
    bool has_text[BTN_NUM];
    stringx default_text[BTN_NUM];
    bool disabled;

public:
    virtual ~HelpbarFE();
};

HelpbarFE::~HelpbarFE()
{
	for(int i=0; i<BTN_NUM; i++)
		delete help_text[i];
}
